--
-- 63 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   svt.k225                27 exercices · 9 chapitres
--   technologie.k226        36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('a2eb4a34-fae7-5b41-9ae6-df3fabc58662'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Dans les coulisses du cœur","competence":"observer-schema","situation":"Le cœur de Samir est représenté de face, comme sur une planche d’anatomie : la moitié droite du corps est à gauche du dessin. Chaque cavité est en blanc, entourée de la paroi musculaire.","documents":[{"id":"coeur","type":"schema","titre":"Le cœur, vu de face","largeur":340,"hauteur":250,"elements":[{"forme":"rect","x":130,"y":44,"l":140,"h":160,"arrondi":22,"teinte":"rose","motif":"plein"},{"forme":"ligne","de":[198,46],"a":[198,202],"teinte":"encre"},{"forme":"rect","x":140,"y":56,"l":52,"h":56,"arrondi":10,"teinte":"blanc","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":204,"y":56,"l":56,"h":56,"arrondi":10,"teinte":"blanc","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":140,"y":128,"l":52,"h":66,"arrondi":10,"teinte":"blanc","motif":"plein","id":"z3","zone":true},{"forme":"rect","x":224,"y":136,"l":30,"h":52,"arrondi":10,"teinte":"blanc","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":116,"y":88,"texte":"Oreillette droite","taille":"petit","ancre":"fin"},{"forme":"ligne","de":[120,84],"a":[140,84],"teinte":"encre"},{"forme":"texte","x":116,"y":164,"texte":"Ventricule droit","taille":"petit","ancre":"fin"},{"forme":"ligne","de":[120,160],"a":[140,160],"teinte":"encre"},{"forme":"texte","x":232,"y":24,"texte":"Oreillette gauche","taille":"petit","ancre":"milieu"},{"forme":"ligne","de":[232,30],"a":[232,56],"teinte":"encre"},{"forme":"texte","x":238,"y":232,"texte":"Ventricule gauche","taille":"petit","ancre":"milieu"},{"forme":"ligne","de":[238,204],"a":[238,218],"teinte":"encre"}]}],"questions":[{"enonce":"Touche la cavité dont la paroi musculaire est la plus épaisse.","aide":"Compare l’épaisseur du muscle rose autour de chaque cavité blanche.","type":"zone","document":"coeur","multiple":false},{"enonce":"Touche la cavité qui reçoit le sang revenant des poumons.","aide":"Après les poumons, le sang revient du côté gauche du cœur, dans la cavité du haut.","type":"zone","document":"coeur","multiple":false},{"enonce":"Une goutte de sang revient de la jambe, chargée de CO₂. Range les étapes de son trajet dans le cœur et les poumons.","aide":"Le sang de retour des organes entre par la droite, va aux poumons, puis revient du côté gauche.","type":"ordre","items":[{"id":"a","texte":"Oreillette droite"},{"id":"b","texte":"Poumons"},{"id":"c","texte":"Ventricule gauche"},{"id":"d","texte":"Ventricule droit"},{"id":"e","texte":"Oreillette gauche"}]},{"enonce":"Pourquoi une cloison étanche sépare-t-elle la moitié droite de la moitié gauche du cœur ?","aide":"Regarde ce que contient le sang de chaque côté.","type":"choix","options":[{"id":"a","texte":"Pour que le cœur pèse moins lourd et batte plus facilement dans la poitrine"},{"id":"b","texte":"Pour que le sang chargé de CO₂ ne se mélange pas au sang riche en dioxygène"},{"id":"c","texte":"Pour que le sang circule plus lentement et laisse le temps aux échanges"},{"id":"d","texte":"Pour filtrer les déchets du sang avant qu’il ne reparte vers les organes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"C’est le **ventricule gauche** : il envoie le sang dans tout l’organisme, il lui faut le muscle le plus puissant."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le sang enrichi en dioxygène arrive dans l’**oreillette gauche**, puis passe dans le ventricule gauche."},{"cle":{"type":"ordre","ids":["a","d","b","e","c"]},"explication":"Dans l’ordre : **oreillette droite, ventricule droit, poumons, oreillette gauche, ventricule gauche**. Le ventricule gauche l’envoie ensuite vers les organes."},{"cle":{"type":"choix","ids":["b"]},"explication":"La cloison empêche tout mélange : le sang à **CO₂** reste à droite, le sang riche en **dioxygène** reste à gauche."}]$ex$::jsonb),
  ('a2eb4a34-fae7-5b41-9ae6-df3fabc58662'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois prises de sang, trois diagnostics","competence":"lire-tableau","situation":"Au laboratoire, trois élèves ont fait une prise de sang. Le tableau donne le contenu d’1 mm³ de sang, avec la valeur habituelle. Les dossiers médicaux sont à droite.","documents":[{"id":"num","type":"tableau","titre":"Numération sanguine","colonnes":["Constituant","Valeur habituelle","Léa","Hugo","Zoé"],"lignes":[["Globules rouges (millions par mm³)","5","3","5","5"],["Globules blancs (milliers par mm³)","7","7","18","6"],["Plaquettes (milliers par mm³)","250","240","260","40"]],"enteteLignes":true,"source":"Valeurs arrondies, dossiers imaginés pour l’exercice"},{"id":"dossiers","type":"texte","genre":"article","titre":"Les trois dossiers","blocs":["Léa, 14 ans : très pâle, essoufflée dès qu’elle monte un escalier.","Hugo, 12 ans : fièvre depuis deux jours et grosse angine.","Zoé, 15 ans : saignements de nez très longs, bleus fréquents."],"source":"Dossiers imaginés pour l’exercice"}],"questions":[{"enonce":"Touche la valeur de Léa qui est anormalement basse.","aide":"Compare chaque valeur de Léa à la colonne « Valeur habituelle ».","type":"zone","document":"num","multiple":false},{"enonce":"Associe chaque élève au constituant du sang qui est anormal chez lui.","aide":"Pour chacun, repère la ligne du tableau où sa valeur s’écarte de la valeur habituelle.","type":"association","gauche":[{"id":"g0","texte":"Léa"},{"id":"g1","texte":"Hugo"},{"id":"g2","texte":"Zoé"}],"droite":[{"id":"d0","texte":"Globules blancs"},{"id":"d1","texte":"Globules rouges"},{"id":"d2","texte":"Plaquettes"}]},{"enonce":"De combien de millions par mm³ les globules rouges de Léa sont-ils en dessous de la valeur habituelle ?","aide":"Soustrais la valeur de Léa à la valeur habituelle.","type":"nombre","unite":"millions par mm³"},{"enonce":"Pourquoi Léa est-elle essoufflée ?","aide":"Quel constituant du sang transporte le dioxygène ?","type":"choix","options":[{"id":"a","texte":"Ses plaquettes ne bouchent plus les vaisseaux, donc son sang circule mal"},{"id":"b","texte":"Ses globules rouges, trop peu nombreux, transportent trop peu de dioxygène"},{"id":"c","texte":"Ses globules blancs attaquent ses poumons, qui captent moins de dioxygène"},{"id":"d","texte":"Son plasma contient trop d’urée, ce qui bloque le transport du dioxygène"}],"multiple":false}]}$ex$::jsonb,
