  ('a2eb4a34-fae7-5b41-9ae6-df3fabc58662'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ce que chaque organe change dans le sang","competence":"analyser-document","situation":"Un laboratoire a dosé le sang qui arrive dans un organe et celui qui en repart. Le schéma montre le trajet complet du sang dans l’organisme.","documents":[{"id":"circuit","type":"chaine","titre":"Le trajet du sang","disposition":"cycle","noeuds":[{"id":"z1","texte":"Cœur droit"},{"id":"z2","texte":"Poumons"},{"id":"z3","texte":"Cœur gauche"},{"id":"z4","texte":"Autres organes"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z1"}]},{"id":"dosages","type":"tableau","titre":"Dosages dans le sang","colonnes":["Organe","Substance","Sang qui arrive","Sang qui repart"],"lignes":[["Poumons","Dioxygène (mL pour 100 mL)","15","20"],["Poumons","Dioxyde de carbone (mL pour 100 mL)","52","48"],["Reins","Urée (g par litre)","0,30","0,18"],["Intestin grêle, après un repas","Glucose (g par litre)","1,0","1,6"],["Muscles en activité","Dioxygène (mL pour 100 mL)","20","12"]],"enteteLignes":true,"source":"Valeurs arrondies, repères pour l’exercice"}],"questions":[{"enonce":"Le sang qui quitte le cœur gauche sort tout juste des poumons. Quelle quantité de dioxygène contient-il pour 100 mL ?","aide":"Regarde dans le schéma ce qui précède le cœur gauche, puis cherche la ligne du tableau.","type":"nombre","unite":"mL"},{"enonce":"Quand 100 mL de sang traversent des muscles en activité, combien de dioxygène perdent-ils ?","aide":"Soustrais la valeur du sang qui repart à celle du sang qui arrive.","type":"nombre","unite":"mL"},{"enonce":"Touche la seule valeur où le sang qui repart contient moins de dioxyde de carbone que celui qui arrive.","aide":"Cherche la ligne « Dioxyde de carbone » et regarde le sens de la variation.","type":"zone","document":"dosages","multiple":false},{"enonce":"Dans les reins, l’urée du sang passe de 0,30 à 0,18 g par litre. Où est passée l’urée manquante ?","aide":"Quel liquide fabriquent les reins ?","type":"choix","options":[{"id":"a","texte":"Elle est restée dans les reins pour toujours"},{"id":"b","texte":"Elle a été expirée par les poumons"},{"id":"c","texte":"Elle a été éliminée dans l’urine"},{"id":"d","texte":"Elle a été transformée en glucose"}],"multiple":false},{"enonce":"Associe chaque organe à ce qui change dans son sang.","aide":"Appuie-toi sur les lignes du tableau : compare « arrive » et « repart ».","type":"association","gauche":[{"id":"g0","texte":"Poumons"},{"id":"g1","texte":"Reins"},{"id":"g2","texte":"Intestin grêle"},{"id":"g3","texte":"Muscles en activité"}],"droite":[{"id":"d0","texte":"Le sang gagne du dioxygène et perd du CO₂"},{"id":"d1","texte":"Le sang gagne du glucose"},{"id":"d2","texte":"Le sang perd de l’urée"},{"id":"d3","texte":"Le sang perd du dioxygène"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 mL","explication":"Le cœur gauche reçoit le sang des poumons : il contient **20 mL** de dioxygène pour 100 mL."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 mL","explication":"20 − 12 = **8 mL** : les cellules musculaires consomment ce dioxygène, qui passe du sang vers elles dans les capillaires."},{"cle":{"type":"zone","ids":["r1c3"]},"explication":"Dans les poumons, le CO₂ passe de 52 à **48 mL** : le sang s’en débarrasse avant de repartir."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les reins filtrent le sang : l’**urée** est éliminée dans l’**urine**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"Les **poumons** enrichissent le sang en O₂, les **reins** l’épurent, l’**intestin** lui apporte les nutriments, les **muscles** lui prennent du dioxygène."}]$ex$::jsonb),
