 point.","type":"zone","document":"tubes","multiple":false},{"enonce":"Touche le tube où un gaz s’est dégagé.","aide":"Cherche dans le tableau la seule valeur différente de 0.","type":"zone","document":"tubes","multiple":false},{"enonce":"La brindille incandescente se rallume dans le gaz du tube A. Quel gaz s’y est dégagé ?","aide":"Quel gaz entretient une combustion ?","type":"choix","options":[{"id":"a","texte":"Du dioxyde de carbone"},{"id":"b","texte":"De l’azote"},{"id":"c","texte":"Du dioxygène"},{"id":"d","texte":"De la vapeur d’eau"}],"multiple":false},{"enonce":"Que montre la comparaison des tubes A et B ?","aide":"Les deux tubes contiennent la même plante : qu’est-ce qui change ?","type":"choix","options":[{"id":"a","texte":"L’élodée ne respire pas"},{"id":"b","texte":"La plante rejette plus de dioxygène dans le noir"},{"id":"c","texte":"La plante ne rejette de dioxygène qu’en présence de lumière"},{"id":"d","texte":"La lumière suffit à produire du dioxygène sans plante"}],"multiple":false}]}$ex$::jsonb,
