  ('ed440b1f-ea9e-524f-b7eb-952a1ae862fc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Jour, nuit et anneau d’écorce","competence":"analyser-document","situation":"Un jardinier étudie un érable. Il mesure d’abord les échanges de dioxyde de carbone d’une feuille au cours d’une journée, puis il observe ce qui se passe quand il retire un anneau d’écorce sur une branche.","documents":[{"id":"jour","type":"graphique","forme":"courbe","titre":"Une feuille au cours d’une journée","categories":["Minuit","6 h","9 h","12 h","15 h","18 h","21 h"],"series":[{"nom":"Photosynthèse","valeurs":[0,1,7,12,8,2,0],"teinte":"vert"},{"nom":"Respiration","valeurs":[2,2,2,2,2,2,2],"teinte":"corail"}],"axeY":{"titre":"Quantité de CO₂ échangée","unite":"unités arbitraires","min":0,"max":14,"pas":2},"axeX":{"titre":"Heure"},"valeurs":false},{"id":"anneau","type":"texte","genre":"article","titre":"Un anneau d’écorce sur une branche","blocs":["Un jardinier retire sur une branche un anneau d’écorce de 2 cm. Le bois, qui contient le xylème, reste intact ; l’écorce, qui contient le phloème, est coupée sur tout le tour.","Trois semaines plus tard, les feuilles de la branche sont toujours vertes. Un renflement s’est formé juste au-dessus de l’anneau, et sous l’anneau la branche ne grossit plus."],"source":"Observation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’heure où la photosynthèse et la respiration s’équilibrent exactement, en fin de journée.","aide":"Cherche le moment où les deux courbes se croisent.","type":"zone","document":"jour","multiple":false},{"enonce":"À midi, que fait la plante du dioxyde de carbone ?","aide":"Compare la valeur de la photosynthèse à celle de la respiration à 12 h.","type":"choix","options":[{"id":"a","texte":"Elle en rejette plus qu’elle n’en consomme"},{"id":"b","texte":"Elle en consomme plus qu’elle n’en rejette"},{"id":"c","texte":"Elle en rejette autant qu’elle en consomme"},{"id":"d","texte":"Elle n’en échange pas"}],"multiple":false},{"enonce":"À minuit, la photosynthèse est nulle. Que montre la courbe de respiration ?","aide":"Regarde si la courbe rouge tombe à zéro.","type":"choix","options":[{"id":"a","texte":"La plante respire aussi la nuit : elle absorbe du dioxygène et rejette du CO₂"},{"id":"b","texte":"La plante rejette du dioxygène la nuit, grâce à la respiration de ses feuilles"},{"id":"c","texte":"La plante ne respire que le jour : la nuit, elle n’absorbe aucun dioxygène"},{"id":"d","texte":"La plante s’arrête de vivre la nuit : elle n’échange plus aucun gaz avec l’air"}],"multiple":false},{"enonce":"Pourquoi les feuilles de la branche restent-elles vertes malgré l’anneau retiré ?","aide":"Quel vaisseau se trouve dans le bois, que le jardinier a conservé ?","type":"choix","options":[{"id":"a","texte":"Les racines ne sont plus utiles à la branche"},{"id":"b","texte":"Les feuilles n’ont plus besoin d’eau"},{"id":"c","texte":"Le xylème, intact, continue d’amener l’eau et les sels minéraux"},{"id":"d","texte":"Le phloème continue d’amener les sucres vers le haut"}],"multiple":false},{"enonce":"Que contient le renflement formé au-dessus de l’anneau ?","aide":"Les sucres fabriqués par les feuilles descendent dans l’écorce.","type":"choix","options":[{"id":"a","texte":"Du dioxygène qui s’accumule sous l’écorce, ce qui fait gonfler le tronc au-dessus"},{"id":"b","texte":"De l’eau qui n’est plus absorbée par les racines et qui stagne dans le tronc"},{"id":"c","texte":"De la sève brute qui ne peut plus monter, bloquée dans sa montée vers les feuilles"},{"id":"d","texte":"De la sève élaborée riche en sucres, bloquée dans sa descente vers les racines"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k5"]},"explication":"À **18 h**, les deux valeurs sont égales (2) : la plante consomme autant de CO₂ qu’elle en rejette."},{"cle":{"type":"choix","ids":["b"]},"explication":"À midi, la photosynthèse (12) l’emporte largement sur la respiration (2) : la plante **absorbe** du CO₂ en net."},{"cle":{"type":"choix","ids":["a"]},"explication":"La respiration est **constante** : la plante respire jour et nuit, et rejette du CO₂ quand la photosynthèse est à l’arrêt."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **xylème** est dans le bois : la sève brute monte toujours vers les feuilles."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le phloème est coupé : la **sève élaborée**, riche en sucres, s’accumule au-dessus de l’anneau."}]$ex$::jsonb),
