   $ex${"titre":"Des SMS pour se rassurer","competence":"analyser-document","situation":"Malo et Jade, 12 ans, échangent des messages sur les changements de leur corps et de leurs émotions.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Malo et Jade","participants":[{"nom":"Malo","emoji":"👦","cote":"gauche"},{"nom":"Jade","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Malo","texte":"Ma voix part dans les aigus puis dans les graves, c’est n’importe quoi !"},{"qui":"Jade","texte":"Normal. Moi, j’ai grandi de 7 cm cette année et mes seins se développent."},{"qui":"Malo","texte":"J’ai aussi envie d’être seul dans ma chambre, et je suis gêné devant mes copains."},{"qui":"Jade","texte":"Pareil, je me sens bizarre. Et Yanis me plaît… je n’ose pas lui dire."}]}],"questions":[{"enonce":"Touche les trois mots qui désignent des caractères sexuels secondaires.","aide":"Cherche les transformations du corps visibles de l’extérieur : voix, taille, poitrine.","type":"zone","document":"sms","multiple":true},{"enonce":"Range ces changements selon leur nature.","aide":"Les organes génitaux sont les caractères primaires ; le reste du corps, les secondaires.","type":"categories","categories":[{"id":"c0","texte":"Caractères sexuels primaires"},{"id":"c1","texte":"Caractères sexuels secondaires"},{"id":"c2","texte":"Changements psychologiques"}],"items":[{"id":"i0","texte":"Les seins se développent"},{"id":"i1","texte":"Les ovaires libèrent des ovules"},{"id":"i2","texte":"Premiers sentiments amoureux"},{"id":"i3","texte":"La voix mue"},{"id":"i4","texte":"Envie d’être plus autonome"},{"id":"i5","texte":"Les testicules fabriquent des spermatozoïdes"}]},{"enonce":"Louna a 13 ans et n’a encore aucun signe de puberté alors que ses amies ont commencé. Que peut-on lui dire ?","aide":"Regarde l’âge moyen de la puberté dans le cours.","type":"choix","options":[{"id":"a","texte":"C’est normal : la puberté commence à des âges très variables, entre 10 et 16 ans"},{"id":"b","texte":"La puberté ne commence qu’à 18 ans, pour toutes les filles sans exception"},{"id":"c","texte":"Elle est malade et doit consulter en urgence : c’est forcément anormal à son âge"},{"id":"d","texte":"Elle ne connaîtra jamais la puberté, puisqu’elle n’a aucun signe à son âge"}],"multiple":false}]}$ex$::jsonb,
