  ('c803accf-3f86-5a4b-b9ae-0c5c267906d5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le message des hormones","competence":"analyser-document","situation":"Hugo a suivi, avec son médecin, le taux d’une hormone sexuelle dans son sang de 8 à 16 ans. Le schéma rappelle comment l’ordre de la puberté arrive jusqu’aux testicules.","documents":[{"id":"chaine","type":"chaine","titre":"Qui commande qui ?","disposition":"colonne","noeuds":[{"id":"z1","texte":"Cerveau"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Testicules"}],"liens":[{"de":"z1","a":"z2","texte":"commande"},{"de":"z2","a":"z3","texte":"hormones dans le sang"}]},{"id":"taux","type":"graphique","forme":"courbe","titre":"Testostérone dans le sang d’Hugo","categories":["8 ans","9 ans","10 ans","11 ans","12 ans","13 ans","14 ans","15 ans","16 ans"],"series":[{"nom":"Testostérone","valeurs":[1,1,1,2,5,10,16,20,22],"teinte":"violet"}],"axeY":{"titre":"Taux de testostérone","unite":"unités arbitraires","min":0,"max":24,"pas":4},"axeX":{"titre":"Âge"},"valeurs":false}],"questions":[{"enonce":"Quelle glande du cerveau, cachée sous le « ? », libère les hormones dans le sang ? (un mot)","aide":"Son nom commence par « hypo- ».","type":"texte"},{"enonce":"Quel est le taux de testostérone d’Hugo à 14 ans ?","aide":"Lis la hauteur du point au-dessus de « 14 ans ».","type":"nombre","unite":"unités"},{"enonce":"De combien le taux augmente-t-il entre 11 ans et 15 ans ?","aide":"Lis le taux à 11 ans, puis à 15 ans, et soustrais.","type":"nombre","unite":"unités"},{"enonce":"La testostérone circule dans tout le sang, mais elle ne modifie que certains organes. Pourquoi ?","aide":"Relis la définition d’une hormone dans le cours.","type":"choix","options":[{"id":"a","texte":"Le cerveau choisit l’organe à chaque fois, en dirigeant la testostérone vers lui"},{"id":"b","texte":"Elle est détruite par tous les autres organes avant d’avoir pu agir sur eux"},{"id":"c","texte":"Seules les cellules capables de la reconnaître réagissent à sa présence"},{"id":"d","texte":"Elle ne circule que dans les testicules, sans jamais passer dans le sang"}],"multiple":false}]}$ex$::jsonb,
