  ('c803accf-3f86-5a4b-b9ae-0c5c267906d5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le calendrier de Camille","competence":"raisonner","situation":"Camille a un cycle régulier de 28 jours. Son jour 1 (J1) est le premier jour de ses règles : le 3 juin. On admet que l’ovulation a lieu au 14e jour du cycle et que les spermatozoïdes survivent jusqu’à 5 jours dans les voies génitales féminines.","documents":[{"id":"frise","type":"frise","titre":"Un cycle de 28 jours","debut":0,"fin":28,"pas":2,"periodes":[{"id":"z1","debut":1,"fin":5,"nom":"Règles","teinte":"ambre"},{"id":"z2","debut":5,"fin":28,"nom":"Muqueuse qui s’épaissit","teinte":"ambre"}],"evenements":[{"id":"z3","date":14,"nom":"Ovulation (J14)"}],"source":"Numéros = jours du cycle"},{"id":"cal","type":"tableau","titre":"Le calendrier de Camille","colonnes":["Jour du cycle","J1","J14","J28"],"lignes":[["Date","3 juin","?","30 juin"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la période où la muqueuse de l’utérus s’épaissit.","aide":"Elle se prépare à accueillir un éventuel embryon, après les règles.","type":"zone","document":"frise","multiple":false},{"enonce":"Quel jour de juin Camille ovule-t-elle ?","aide":"J1 est le 3 juin : J2 est le 4 juin, et ainsi de suite jusqu’à J14.","type":"nombre","unite":"juin"},{"enonce":"Camille a un rapport non protégé le 14 juin. Une grossesse est-elle possible ?","aide":"Compte les jours entre le rapport et l’ovulation, puis compare à la survie des spermatozoïdes.","type":"choix","options":[{"id":"a","texte":"Oui, mais seulement si elle ovule le jour même du rapport non protégé, le 14 juin"},{"id":"b","texte":"Non : une grossesse est impossible avant les prochaines règles, quelle que soit la date"},{"id":"c","texte":"Non : l’ovulation n’a pas encore eu lieu, donc il ne peut y avoir de fécondation"},{"id":"d","texte":"Oui : les spermatozoïdes peuvent être encore vivants lors de l’ovulation, le 16 juin"}],"multiple":false},{"enonce":"Sans fécondation, ses prochaines règles commenceront un jour de juillet. Lequel ?","aide":"Le cycle dure 28 jours : ajoute 28 jours au 3 juin.","type":"nombre","unite":"juillet"},{"enonce":"Léna, 12 ans, n’a pas encore eu ses premières règles. Peut-elle déjà être enceinte ?","aide":"Dans quel ordre arrivent la première ovulation et les premières règles ?","type":"choix","options":[{"id":"a","texte":"Non : sans règles, il n’y a jamais d’ovulation"},{"id":"b","texte":"Oui, mais seulement si ses cycles sont réguliers"},{"id":"c","texte":"Non : avant 14 ans, c’est impossible"},{"id":"d","texte":"Oui : la première ovulation précède les premières règles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **muqueuse qui s’épaissit** occupe la seconde partie du cycle."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16 juin","explication":"J14 = 3 + 13 = le **16 juin**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le rapport a lieu **2 jours** avant l’ovulation, moins que les 5 jours de survie des spermatozoïdes : la fécondation est possible."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 juillet","explication":"3 juin + 28 jours = le **1er juillet**, nouveau J1."},{"cle":{"type":"choix","ids":["d"]},"explication":"La première ovulation **précède** les premières règles : une grossesse est possible avant elles."}]$ex$::jsonb),
  ('f2130db8-f255-5382-adfd-6b2b47f073e8'::uuid, 1, 1, 5, 20, 3,
