  ('b23b9967-5919-50f9-8cf5-d78fc65e4647'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Malik et la perceuse","competence":"analyser-texte","situation":"Lors d’une séance de perçage, Malik commet plusieurs erreurs. Son voisin les remarque, mais ne sait pas comment réagir.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"La séance de Malik","auteur":"Texte écrit pour l’exercice","blocs":["Malik doit percer une plaque. Il enfile des gants pour mieux la tenir, laisse ses cheveux longs détachés et relève le carter de la perceuse pour voir le foret.","La machine tourne encore quand il règle la butée. Son voisin, qui attendait son tour, le regarde faire sans rien dire."]}],"questions":[{"enonce":"Touche l’accessoire qu’il ne faut jamais porter près d’une pièce en rotation.","aide":"Il est censé protéger les mains, mais il peut être happé.","type":"zone","document":"recit","multiple":false},{"enonce":"Touche le verbe qui décrit un réglage fait alors que la machine tourne encore.","aide":"Cherche le verbe lié à la butée.","type":"zone","document":"recit","multiple":false},{"enonce":"Range dans l’ordre les gestes que Malik aurait dû faire.","aide":"On demande avant d’agir, on se protège avant de démarrer, on règle et on range à l’arrêt.","type":"ordre","items":[{"id":"a","texte":"Ranger l’outil et dégager le poste"},{"id":"b","texte":"Mettre ses lunettes et attacher ses cheveux"},{"id":"c","texte":"Démarrer la machine et percer"},{"id":"d","texte":"Attendre l’arrêt complet"},{"id":"e","texte":"Demander l’autorisation à l’enseignant"}]},{"enonce":"Que doit faire le voisin de Malik ?","aide":"Le bouton rouge sur fond jaune coupe tout immédiatement.","type":"choix","options":[{"id":"a","texte":"Appeler Malik pour le distraire et lui parler pendant qu’il travaille"},{"id":"b","texte":"Mettre des gants et l’aider à régler le foret pendant que la perceuse tourne"},{"id":"c","texte":"Appuyer tout de suite sur l’arrêt d’urgence, puis prévenir l’enseignant"},{"id":"d","texte":"Attendre que Malik ait fini son réglage avant d’intervenir auprès de lui"}],"multiple":false}]}$ex$::jsonb,
