  ('e19df25a-1a55-5cb6-b07d-0f6b06d125bc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La revue de projet du bras robot","competence":"raisonner","situation":"Une équipe construit un bras robot. Elle compare son planning prévu avec les événements notés dans son carnet de bord. Le projet démarre au jour 0.","documents":[{"id":"planning","type":"tableau","titre":"Le planning prévu","colonnes":["Tâche","Durée (jours)","Doit être finie avant"],"lignes":[["A. Analyse du besoin","2","—"],["B. Recherche de solutions","2","A"],["C. Conception","3","B"],["D. Réalisation","4","C"],["E. Programmation","3","C"],["F. Tests","2","D et E"]],"enteteLignes":true,"source":"Projet imaginé pour l’exercice"},{"id":"carnet","type":"texte","genre":"recit","titre":"Le carnet de bord","auteur":"Texte écrit pour l’exercice","blocs":["Lundi. Le premier prototype casse dès l’essai de charge : la plaque de deux millimètres plie sous le poids.","Mardi. Nouveau prototype avec une plaque de trois millimètres : le test est réussi. Les deux essais sont notés dans le carnet.","Mercredi. Le fournisseur n’a plus de plaques : la tâche « Réalisation » sera retardée de 2 jours."]}],"questions":[{"enonce":"D’après le planning prévu, quelle est la durée totale du projet ?","aide":"A, B et C se suivent (7 jours). Puis D et E se font en même temps, puis F.","type":"nombre","unite":"jours"},{"enonce":"Quelle tâche dispose d’une marge avant F ?","aide":"Compare les fins de D et de E : F attend la plus tardive.","type":"choix","options":[{"id":"a","texte":"Les tests"},{"id":"b","texte":"La réalisation"},{"id":"c","texte":"La programmation"},{"id":"d","texte":"La conception"}],"multiple":false},{"enonce":"Touche l’épaisseur de plaque qui a réussi l’essai de charge.","aide":"Lis le compte rendu du mardi.","type":"zone","document":"carnet","multiple":false},{"enonce":"La réalisation (D) prend 2 jours de retard. Quelle est la nouvelle durée totale du projet ?","aide":"D se termine alors au jour 13, et F attend D.","type":"nombre","unite":"jours"},{"enonce":"Dans le planning prévu (sans retard de D), c’est la programmation (E) qui prend 2 jours de retard. Quelle est alors la durée totale ?","aide":"E se termine au jour 10 + 2 = 12 : plus tard que D (jour 11).","type":"nombre","unite":"jours"}]}$ex$::jsonb,
