   $ex${"titre":"Trois générations de lampe Lumi","competence":"lire-tableau","situation":"La lampe Lumi existe en trois générations. Elles éclairent aussi bien l’une que l’autre, mais l’entreprise l’a améliorée à chaque fois.","documents":[{"id":"lumi","type":"tableau","titre":"Les trois générations","colonnes":["Génération","Source de lumière","Puissance (W)","Masse (g)"],"lignes":[["1","Ampoule à filament","60","450"],["2","Ampoule fluocompacte","11","380"],["3","Ampoule à LED","7","300"]],"enteteLignes":false,"source":"Produit imaginé pour l’exercice"}],"questions":[{"enonce":"Ces trois lampes forment…","aide":"C’est le même modèle, amélioré génération après génération.","type":"choix","options":[{"id":"a","texte":"Un seul système technique"},{"id":"b","texte":"Une lignée d’objets techniques"},{"id":"c","texte":"Une chaîne d’énergie"},{"id":"d","texte":"Une famille d’objets techniques"}],"multiple":false},{"enonce":"De combien de watts la puissance baisse-t-elle entre la génération 1 et la génération 3 ?","aide":"Soustrais 7 à 60.","type":"nombre","unite":"W"},{"enonce":"Quelle énergie la lampe de génération 3 consomme-t-elle en 1 000 heures ? (Puissance × durée, en kilowattheures)","aide":"Multiplie 7 W par 1 000 h : tu obtiens des Wh. 1 000 Wh font 1 kWh.","type":"nombre","unite":"kWh"},{"enonce":"Le passage à la LED s’explique surtout par…","aide":"La lampe éclaire toujours : ce qui change, c’est la manière d’y parvenir.","type":"choix","options":[{"id":"a","texte":"Une mode sans aucune raison technique"},{"id":"b","texte":"Le progrès technique : une source de lumière plus économe"},{"id":"c","texte":"Un changement de fonction d’usage : la lampe ne sert plus à éclairer"},{"id":"d","texte":"La disparition du besoin d’éclairer"}],"multiple":false}]}$ex$::jsonb,
